import {useState} from 'react'
import {Heading, Link, UnderlineNav} from '@primer/react'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import styles from './RegistryConfigurationCard.module.css'

interface RegistryConfigurationCardProps {
  enterpriseSlug: string
}

type InstallMethodId = 'npmrc' | 'npm-config' | 'env'

interface InstallMethod {
  id: InstallMethodId
  label: string
  snippet: string
}

const TOKEN_PLACEHOLDER = '${GITHUB_TOKEN}'

const GITHUB_TOKEN_DOCS_URL =
  'https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens'
const ACTIONS_SECRETS_DOCS_URL =
  'https://docs.github.com/en/actions/security-for-github-actions/security-guides/using-secrets-in-github-actions'

// Leading comment baked into every snippet so the guidance travels with whatever the user copies.
// Single line so the snippet box wraps it naturally instead of forcing hard line breaks.
const TOKEN_GUIDANCE_COMMENT = `# Replace ${TOKEN_PLACEHOLDER} with a GitHub token that has access to this enterprise. Avoid committing it to a repository and store it securely (for example, in your user-level npm config or CI secrets).`

function buildInstallMethods(slug: string): Record<InstallMethodId, InstallMethod> {
  const host = 'package-firewall.githubapp.com'
  const registryPath = `/npm/enterprises/${slug}`
  const registryUrl = `https://${host}${registryPath}`
  const authKey = `//${host}${registryPath}/:_authToken`

  return {
    npmrc: {
      id: 'npmrc',
      label: '.npmrc',
      snippet: `${TOKEN_GUIDANCE_COMMENT}\n\nregistry=${registryUrl}\n${authKey}=${TOKEN_PLACEHOLDER}`,
    },
    'npm-config': {
      id: 'npm-config',
      label: 'npm config',
      snippet: `${TOKEN_GUIDANCE_COMMENT}\n\nnpm config set registry ${registryUrl}\nnpm config set ${authKey}=${TOKEN_PLACEHOLDER}`,
    },
    env: {
      id: 'env',
      label: 'CI / containers',
      // npm only supports `${VAR}` interpolation inside .npmrc — host-scoped env var names contain
      // `/` and `:` and can't be set via bash `export`, so a minimal .npmrc is still required.
      snippet: `${TOKEN_GUIDANCE_COMMENT}\n\n# .npmrc\nregistry=${registryUrl}\n${authKey}=\${NPM_TOKEN}\n\n# In your CI or container environment:\nexport NPM_TOKEN=${TOKEN_PLACEHOLDER}`,
    },
  }
}

const METHOD_ORDER: InstallMethodId[] = ['npmrc', 'npm-config', 'env']

export function RegistryConfigurationCard({enterpriseSlug}: RegistryConfigurationCardProps) {
  const methods = buildInstallMethods(enterpriseSlug)
  const [selectedId, setSelectedId] = useState<InstallMethodId>('npmrc')
  const selected = methods[selectedId]

  return (
    <div className={styles.section}>
      <Heading as="h3" className={`f4 ${styles.sectionHeading}`}>
        Configure npm registry access
      </Heading>
      <p className={styles.sectionDescription}>
        Set up the package firewall as your private npm registry for this enterprise with a{' '}
        <Link inline href={GITHUB_TOKEN_DOCS_URL} target="_blank" rel="noopener noreferrer">
          GitHub token
        </Link>
        . Securely store tokens with{' '}
        <Link inline href={ACTIONS_SECRETS_DOCS_URL} target="_blank" rel="noopener noreferrer">
          Actions secrets and variables
        </Link>
        .
      </p>

      <div className={styles.tabsCard}>
        <UnderlineNav aria-label="Installation method" className={styles.underlineNav}>
          {METHOD_ORDER.map(id => (
            <UnderlineNav.Item
              key={id}
              as="button"
              aria-current={id === selectedId ? 'page' : undefined}
              onSelect={() => setSelectedId(id)}
            >
              {methods[id].label}
            </UnderlineNav.Item>
          ))}
        </UnderlineNav>

        <div className={styles.snippetBox}>
          <pre className={styles.snippet}>{selected.snippet}</pre>
          <CopyToClipboardButton
            textToCopy={selected.snippet}
            ariaLabel={`Copy ${selected.label} configuration`}
            size="small"
            tooltipProps={{direction: 'w'}}
          />
        </div>
      </div>
    </div>
  )
}
