import {useRef, useState, type ReactNode} from 'react'
import {ActionList, ActionMenu, Dialog, FormControl, Heading, IconButton, TextInput, ToggleSwitch} from '@primer/react'
import {clsx} from 'clsx'
import {PencilIcon} from '@primer/octicons-react'

import styles from './PolicySettingsTab.module.css'
import {useMutation, useQueryClient} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {policyEndpoint, getPolicyQueryKey} from '../queries/use-policy-query'
import {updatePolicyMutationOptions} from '../queries/update-policy'
import type {PolicyResponse, PolicySettings, SeverityThreshold} from '../types'

interface PolicySettingsTabProps {
  enterpriseSlug: string
  policy: PolicySettings
  onSaveError: (message: string) => void
  onSaveStart: () => void
}

interface SettingRowProps {
  id: string
  title: string
  description: ReactNode
  checked: boolean
  onChange: (checked: boolean) => void
  isLast?: boolean
  children?: ReactNode
}

function SettingRow({id, title, description, checked, onChange, isLast, children}: SettingRowProps) {
  const showBorder = !(isLast && !children)
  return (
    <>
      <div className={clsx(styles.settingRow, showBorder && styles.settingRowBorder)}>
        <div className={styles.flexContent}>
          <span id={id} className={styles.boldLabel}>
            {title}
          </span>
          <span className={styles.mutedDescription}>{description}</span>
        </div>
        <div className={styles.toggleWrapper}>
          <ToggleSwitch aria-labelledby={id} checked={checked} onClick={() => onChange(!checked)} size="small" />
        </div>
      </div>
      {children}
    </>
  )
}

function SectionCard({children}: {children: ReactNode}) {
  return <div className={styles.sectionCard}>{children}</div>
}

function SectionHeading({children, description}: {children: ReactNode; description?: ReactNode}) {
  return (
    <div className={styles.sectionHeading}>
      <Heading as="h3" className="f4">
        {children}
      </Heading>
      {description ? <p className={styles.sectionDescription}>{description}</p> : null}
    </div>
  )
}

const SEVERITY_OPTIONS: ReadonlyArray<{value: SeverityThreshold; label: string}> = [
  {value: 'none', label: 'Off'},
  {value: 'critical', label: 'Critical only'},
  {value: 'high', label: 'High or higher'},
  {value: 'medium', label: 'Medium or higher'},
  {value: 'low', label: 'Low or higher'},
]

interface SeveritySelectRowProps {
  value: SeverityThreshold
  onChange: (value: SeverityThreshold) => void
  isLast?: boolean
}

function SeveritySelectRow({value, onChange, isLast}: SeveritySelectRowProps) {
  const id = 'setting-advisory-severity-threshold'
  const labelId = `${id}-label`
  const currentLabel = SEVERITY_OPTIONS.find(opt => opt.value === value)?.label ?? value
  return (
    <div className={clsx(styles.settingRow, !isLast && styles.settingRowBorder)}>
      <div className={styles.flexContent}>
        <span id={labelId} className={styles.boldLabel}>
          Severity threshold
        </span>
        <span className={styles.mutedDescription}>
          Block packages affected by advisories at or above the selected severity level.
        </span>
      </div>
      <div className={styles.toggleWrapper}>
        <ActionMenu>
          <ActionMenu.Button id={id} aria-labelledby={`${labelId} ${id}`}>
            {currentLabel}
          </ActionMenu.Button>
          <ActionMenu.Overlay width="medium">
            <ActionList selectionVariant="single">
              {SEVERITY_OPTIONS.map(opt => (
                <ActionList.Item key={opt.value} selected={opt.value === value} onSelect={() => onChange(opt.value)}>
                  {opt.label}
                </ActionList.Item>
              ))}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>
    </div>
  )
}

const HOURS_PER_DAY = 24
const MAX_DAYS = 365

interface PackageAgeRowProps {
  hours: number
  onChange: (hours: number) => void
  isLast?: boolean
}

function PackageAgeRow({hours, onChange, isLast}: PackageAgeRowProps) {
  const isExactDays = hours > 0 ? hours % HOURS_PER_DAY === 0 : true
  const days = Math.floor(hours / HOURS_PER_DAY)
  const [isOpen, setIsOpen] = useState(false)
  const [draftValue, setDraftValue] = useState(String(days))
  const titleId = 'setting-package-age-title'

  const openEditor = () => {
    setDraftValue(String(days))
    setIsOpen(true)
  }

  const closeEditor = () => setIsOpen(false)

  const onSave = () => {
    const parsed = parseInt(draftValue, 10)
    const clampedDays = isNaN(parsed) ? 0 : Math.min(Math.max(parsed, 0), MAX_DAYS)
    onChange(clampedDays * HOURS_PER_DAY)
    setIsOpen(false)
  }

  const currentLabel = isExactDays ? (days === 1 ? '1 day' : `${days} days`) : hours === 1 ? '1 hour' : `${hours} hours`

  return (
    <>
      <div className={clsx(styles.settingRowCenter, !isLast && styles.settingRowBorder)}>
        <div className={styles.flexContent}>
          <span id={titleId} className={styles.boldLabel}>
            Minimum package age
          </span>
          <span className={styles.mutedDescription}>
            Require packages be published for a specific number of days before they can be installed. This gives the
            community time to discover issues in new releases.
          </span>
        </div>
        <div className={styles.ageControlWrapper}>
          <span className={styles.mutedText}>{currentLabel}</span>
          <IconButton
            icon={PencilIcon}
            aria-label="Edit minimum package age"
            variant="invisible"
            size="small"
            onClick={openEditor}
          />
        </div>
      </div>
      {isOpen ? (
        <Dialog
          title="Minimum package age"
          onClose={closeEditor}
          footerButtons={[
            {buttonType: 'default', content: 'Cancel', onClick: closeEditor},
            {buttonType: 'primary', content: 'Save', onClick: onSave},
          ]}
        >
          <FormControl>
            <FormControl.Label>Days</FormControl.Label>
            <TextInput
              type="number"
              min={0}
              max={MAX_DAYS}
              value={draftValue}
              onChange={e => setDraftValue(e.target.value)}
              autoFocus
              block
            />
            <FormControl.Caption>
              {isExactDays
                ? `Set to 0 to disable the cooldown. Maximum is ${MAX_DAYS} days.`
                : `Current value is ${hours} hours. Saving will replace it with the number of days entered above.`}
            </FormControl.Caption>
          </FormControl>
        </Dialog>
      ) : null}
    </>
  )
}

export function PolicySettingsTab({enterpriseSlug, policy, onSaveError, onSaveStart}: PolicySettingsTabProps) {
  const queryClient = useQueryClient()
  const mutation = useMutation(updatePolicyMutationOptions(enterpriseSlug))
  const queryKey = getPolicyQueryKey(enterpriseSlug)

  // Mutations are serialized through `queueRef` so the PATCH endpoint (which always
  // overwrites the full policy) sees them in click order. `pendingRef` lets the last
  // mutation in the queue reconcile the cache with the server response without flicker.
  const queueRef = useRef<Promise<void>>(Promise.resolve())
  const pendingRef = useRef(0)

  const update = (patch: Partial<PolicySettings>) => {
    const cachedPolicy = queryClient.getQueryData<PolicyResponse>(queryKey)?.policy ?? policy
    const next = {...cachedPolicy, ...patch}
    queryClient.setQueryData<PolicyResponse>(queryKey, {policy: next})
    onSaveStart()
    pendingRef.current += 1

    const previousQueue = queueRef.current
    queueRef.current = (async () => {
      await previousQueue
      // Read from the cache at execution time so any optimistic changes that were
      // queued after this one are folded into the request body.
      const policyToSend = queryClient.getQueryData<PolicyResponse>(queryKey)?.policy ?? next
      try {
        const result = await mutation.mutateAsync({policy: policyToSend})
        pendingRef.current -= 1
        if (pendingRef.current === 0) {
          queryClient.setQueryData<PolicyResponse>(queryKey, result)
        }
      } catch {
        pendingRef.current -= 1
        // Best-effort recovery: refetch the server's source of truth so the UI stops
        // showing optimistic state that didn't actually persist.
        try {
          const response = await verifiedFetch(policyEndpoint(enterpriseSlug), {
            headers: {Accept: 'application/json'},
          })
          if (response.ok) {
            const truth = (await response.json()) as PolicyResponse
            queryClient.setQueryData<PolicyResponse>(queryKey, truth)
          }
        } catch {
          // If even the refetch fails, leave the optimistic cache in place — the page
          // banner above will tell the user something is off.
        }
        onSaveError("Couldn't save your change. Please try again.")
      }
    })()
  }

  return (
    <div className={styles.pageLayout}>
      <div>
        <SectionHeading description="Prevent dangerous packages from being installed.">
          Advisories and malware
        </SectionHeading>
        <SectionCard>
          <SettingRow
            id="setting-block-malware"
            title="Block known malware"
            description="Prevent installation of packages flagged as malware by GitHub Advisory Database. Recommended for all enterprises."
            checked={policy.blockMalware}
            onChange={v => update({blockMalware: v})}
          />
          <SeveritySelectRow
            value={policy.severityThreshold}
            onChange={threshold => update({severityThreshold: threshold})}
            isLast
          />
        </SectionCard>
      </div>

      <div>
        <SectionHeading description="Require packages to meet supply chain integrity checks.">
          Supply chain verification
        </SectionHeading>
        <SectionCard>
          <SettingRow
            id="setting-block-attestation-downgrade"
            title="Block attestation downgrades"
            description="Block package versions that drop SLSA provenance attestations when previous versions had them. This is a strong signal of supply chain compromise."
            checked={policy.blockAttestationDowngrade}
            onChange={v => update({blockAttestationDowngrade: v})}
          />
          <SettingRow
            id="setting-block-added-scripts"
            title="Block newly introduced install scripts"
            description="Block package versions that introduce preinstall, install, or postinstall lifecycle scripts when previous versions didn't have them. Install scripts execute arbitrary code and are a primary vector for supply chain attacks."
            checked={policy.blockAddedScripts}
            onChange={v => update({blockAddedScripts: v})}
          />
          <PackageAgeRow hours={policy.minimumPackageAge} onChange={h => update({minimumPackageAge: h})} isLast />
        </SectionCard>
      </div>
    </div>
  )
}
