import {useQuery} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {PolicyResponse} from '../types'

export const getPolicyQueryKey = (enterpriseSlug: string) => [
  'package-firewall-enterprise-settings',
  'policy',
  enterpriseSlug,
]

export function policyEndpoint(enterpriseSlug: string) {
  return `/enterprises/${enterpriseSlug}/settings/policies/package_firewall`
}

export function usePolicyQuery({enterpriseSlug, initialData}: {enterpriseSlug: string; initialData: PolicyResponse}) {
  return useQuery({
    queryKey: getPolicyQueryKey(enterpriseSlug),
    queryFn: async (): Promise<PolicyResponse> => {
      const response = await verifiedFetch(policyEndpoint(enterpriseSlug), {
        headers: {Accept: 'application/json'},
      })
      if (!response.ok) {
        throw new Error(`Failed to fetch package firewall policy for ${enterpriseSlug}: ${response.status}`)
      }
      return response.json()
    },
    enabled: false,
    initialData,
  })
}
