import type {PackageEcosystem} from '../types'

interface PatternHints {
  /** Caption shown beneath the package-name input. */
  nameDescription: string
  /** Examples shown beneath the package-name input. */
  nameExamples: string[]
  /** Caption shown beneath the version input. */
  versionDescription: string
  /** Examples shown beneath the version input. */
  versionExamples: string[]
}

const HINTS: Record<PackageEcosystem, PatternHints> = {
  npm: {
    nameDescription: 'Use * as a wildcard to match multiple packages.',
    nameExamples: ['octo-package', '@scope/pkg', '@scope/*'],
    versionDescription: 'Leave empty to match all versions. Accepts any npm semver range.',
    versionExamples: ['1.2.3', '^1.2.3', '~1.2.3', '1.x', '>=1.0.0 <2.0.0'],
  },
}

export function patternHintsFor(ecosystem: PackageEcosystem): PatternHints {
  return HINTS[ecosystem]
}
