import {useQuery} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {OverrideType, PackageOverride} from '../types'

export const getOverridesQueryKey = (enterpriseSlug: string, type: OverrideType) => [
  'package-firewall-enterprise-settings',
  'overrides',
  enterpriseSlug,
  type,
]

export function overridesEndpoint(enterpriseSlug: string, type: OverrideType) {
  const params = new URLSearchParams({type})
  return `/enterprises/${enterpriseSlug}/settings/policies/package_firewall/overrides?${params.toString()}`
}

export function useOverridesQuery({
  enterpriseSlug,
  type,
  initialData,
}: {
  enterpriseSlug: string
  type: OverrideType
  initialData?: PackageOverride[]
}) {
  return useQuery({
    queryKey: getOverridesQueryKey(enterpriseSlug, type),
    queryFn: async (): Promise<PackageOverride[]> => {
      const response = await verifiedFetch(overridesEndpoint(enterpriseSlug, type), {
        headers: {Accept: 'application/json'},
      })
      if (!response.ok) {
        throw new Error(`Failed to fetch ${type} overrides for ${enterpriseSlug}: ${response.status}`)
      }
      return response.json()
    },
    enabled: false,
    initialData,
  })
}
