import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {PackageFirewallEnterpriseSettings} from '../PackageFirewallEnterpriseSettings'
import {packageFirewallEnterpriseSettingsRoute} from './package-firewall-enterprise-settings-route'

export function PackageFirewallEnterpriseSettingsRoute() {
  const {enterprise} = useRouteParams(packageFirewallEnterpriseSettingsRoute)
  const {data} = useRouteQuery(packageFirewallEnterpriseSettingsRoute, 'mainQuery')

  if (!data) return null

  return (
    <PackageFirewallEnterpriseSettings
      enterpriseSlug={enterprise}
      policy={data.policy}
      allowedPackages={data.allowedPackages}
      blockedPackages={data.blockedPackages}
    />
  )
}
